const BASE_URL = "https://gdi.bsh.de/ldproxy/rest/services/WaterLevelForecast/collections/waterlevelforecastdata/items";
const APP_VERSION = "1.0.39";

// Edit this for the target system:
// Windows Signal K: "C:\\signalk\\signalkhome\\.signalk\\bsh-tides-cache"
// OpenPlotter/Raspberry Pi: "/home/pi/.signalk/bsh-tides-cache"
const CACHE_DIR = flow.get("bshCacheDir") || "C:\\signalk\\signalkhome\\.signalk\\bsh-tides-cache";
const SEAWEATHER_CACHE_DIR = flow.get("seaWeatherCacheDir") || "C:\\signalk\\signalkhome\\.signalk\\bsh-seaweather-cache";
const PEGELONLINE_CACHE_DIR = flow.get("pegelOnlineCacheDir") || "C:\\signalk\\signalkhome\\.signalk\\pegelonline-cache";
const NAVTEX_CACHE_DIR = flow.get("navtexCacheDir") || "C:\\signalk\\signalkhome\\.signalk\\navtex-cache";

let state = flow.get("bshTidesDashboard") || {
  stations: [],
  activeStationId: "",
  selectedStations: [],
  loaded: {},
  offlineIndex: {},
  seaWeatherIndex: {},
  navtexIndex: {},
  mode: "online",
  status: "Bereit"
};

function saveState() {
  flow.set("bshTidesDashboard", state);
}

function safeId(id) {
  return String(id || "").replace(/[^a-zA-Z0-9_-]/g, "_");
}

function joinPath(dir, file) {
  const sep = dir.includes("\\") ? "\\" : "/";
  return dir.replace(/[\\\/]+$/, "") + sep + file;
}

function isPathInside(baseDir, targetPath) {
  try {
    if (typeof path !== "undefined" && path.resolve && path.relative) {
      const base = path.resolve(String(baseDir || ""));
      const target = path.resolve(String(targetPath || ""));
      const rel = path.relative(base, target);
      return !!rel && rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel);
    }
  } catch (e) {}
  const base = String(baseDir || "").replace(/[\\\/]+$/, "").toLowerCase();
  const target = String(targetPath || "").replace(/[\\\/]+$/, "").toLowerCase();
  return !!base && target.startsWith(base + (base.includes("\\") ? "\\" : "/"));
}

function htmlEscape(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function twoDigits(value) {
  return String(value).padStart(2, "0");
}

function seaWeatherStamp(date) {
  return twoDigits(date.getDate()) + "." + twoDigits(date.getMonth() + 1) + "." + date.getFullYear() + "_" + twoDigits(date.getHours()) + twoDigits(date.getMinutes());
}

function fileStamp(date) {
  return date.getFullYear() + twoDigits(date.getMonth() + 1) + twoDigits(date.getDate()) + "-" + twoDigits(date.getHours()) + twoDigits(date.getMinutes()) + twoDigits(date.getSeconds());
}

function htmlToText(value) {
  return String(value ?? "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<(br|\/p|\/div|\/li|\/tr|h[1-6])\b[^>]*>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, "")
    .replace(/[ \t]+/g, " ")
    .replace(/\n[ \t]+/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function extractPreText(value) {
  const html = String(value ?? "");
  const match = html.match(/<pre\b[^>]*>([\s\S]*?)<\/pre>/i);
  if (!match) return "";
  return String(match[1])
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{4,}/g, "\n\n\n")
    .trim();
}

function summarizePolardata(value) {
  let data;
  try {
    data = typeof value === "string" ? JSON.parse(value) : value;
  } catch (e) {
    return htmlToText(value) || "Polardata konnte nicht als JSON gelesen werden: " + e.message;
  }
  const boats = Array.isArray(data) ? data : [];
  if (!boats.length) return "Polardata: keine Bootsdaten gefunden.";
  const lines = [
    "ORC Polardata",
    "Quelle: jieter/orc-data/orc-data.json",
    "Datensätze: " + boats.length,
    "",
    "Auszug:",
    ""
  ];
  for (const boat of boats.slice(0, 80)) {
    const name = boat.name || "-";
    const type = boat.boat && boat.boat.type ? boat.boat.type : "-";
    const sail = boat.sailnumber || "-";
    const country = boat.country || "-";
    const gph = boat.rating && boat.rating.gph !== undefined ? boat.rating.gph : "-";
    const loa = boat.boat && boat.boat.sizes && boat.boat.sizes.loa !== undefined ? boat.boat.sizes.loa + " m" : "-";
    lines.push(name + " · " + type + " · " + sail + " · " + country + " · GPH " + gph + " · LOA " + loa);
  }
  lines.push("");
  lines.push("Hinweis: Anzeige gekürzt auf 80 Einträge. Die vollständigen Polar-/VPP-Werte bleiben in der Quelle enthalten.");
  return lines.join("\n");
}

function parsePegelonlineStammdaten(value, pegelnr) {
  const text = htmlToText(value);
  function lineValue(label) {
    const escaped = label.replace(/[-\/\\^$*+?.()|[\]{}]/g, "\\$&");
    const re = new RegExp(escaped + "\\s+([^\\n]+)", "i");
    const match = text.match(re);
    return match ? match[1].trim() : "";
  }
  function measurement(label) {
    const escaped = label.replace(/[-\/\\^$*+?.()|[\]{}]/g, "\\$&");
    const re = new RegExp(escaped + "\\s+([^\\s]+)\\s+([0-9]{2}\\.[0-9]{2}\\.[0-9]{4}\\s+[0-9]{2}:[0-9]{2}\\s+Uhr)", "i");
    const match = text.match(re);
    return match ? { value: match[1], time: match[2] } : { value: "", time: "" };
  }
  const water = measurement("Wasserstand [cm]");
  const windSpeed = measurement("Windgeschwindigkeit [m/s]");
  const windDirection = measurement("Windrichtung [Grad]");
  return {
    pegelnr: pegelnr || lineValue("Messstellennummer"),
    url: "https://www.pegelonline.wsv.de/gast/stammdaten?pegelnr=" + encodeURIComponent(pegelnr || lineValue("Messstellennummer")),
    fetchedAt: new Date().toISOString(),
    stammdaten: {
      messstellenname: lineValue("Messstellenname"),
      messstellennummer: lineValue("Messstellennummer"),
      gewaesser: lineValue("Gewässer"),
      kilometer: lineValue("Kilometer an der Wasserstraße"),
      pnp: lineValue("gültig ab"),
      uuid: lineValue("Messstellenuuid")
    },
    values: {
      water,
      windSpeed,
      windDirection
    }
  };
}

function cmToM(value) {
  if (value === undefined || value === null || value === "") return null;
  const n = Number(String(value).replace(",", "."));
  return Number.isFinite(n) ? n / 100 : null;
}

function eventSeriesPoint(e, key, name, color, valueField, deviationField, timestampField) {
  const x = toMs(e.event_timestamp);
  const height = cmToM(e[valueField]);
  if (!x || height === null) return null;
  return {
    x,
    time: new Date(x).toISOString(),
    event: e.event,
    label: e.event === "HW" ? "HW" : e.event === "NW" ? "NW" : e.event,
    seriesKey: key,
    seriesName: name,
    color,
    height,
    deviation: e[deviationField] || "",
    forecastTimestamp: toIso(e[timestampField])
  };
}

function toIso(value) {
  if (!value) return null;
  const d = new Date(String(value).replace(" ", "T"));
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function toMs(value) {
  const iso = toIso(value);
  return iso ? Date.parse(iso) : null;
}

function latestTimestamp(points) {
  return points.reduce((latest, point) => {
    const x = point && point.x;
    return x && (!latest || x > latest) ? x : latest;
  }, null);
}

function earliestTimestamp(points) {
  let earliest = null;
  for (const point of points) {
    const x = point && point.x;
    if (x && (earliest === null || x < earliest)) {
      earliest = x;
    }
  }
  return earliest;
}

function interpolateExtrema(points, stepMinutes) {
  const sorted = points
    .filter(p => p.x && Number.isFinite(p.y))
    .sort((a, b) => a.x - b.x);
  if (sorted.length < 2) return [];
  const step = Math.max(5, stepMinutes || 10) * 60 * 1000;
  const result = [];
  for (let i = 0; i < sorted.length - 1; i++) {
    const a = sorted[i];
    const b = sorted[i + 1];
    const span = b.x - a.x;
    if (span <= 0) continue;
    for (let x = a.x; x < b.x; x += step) {
      const t = (x - a.x) / span;
      const smooth = (1 - Math.cos(Math.PI * t)) / 2;
      result.push({ x, y: a.y + (b.y - a.y) * smooth, synthetic: true });
    }
  }
  const last = sorted[sorted.length - 1];
  result.push({ x: last.x, y: last.y, synthetic: true });
  return result;
}

function summarizeFeature(feature) {
  const p = feature.properties || {};
  const curve = Array.isArray(p.curve) ? p.curve : [];
  const events = Array.isArray(p.high_water_low_water) ? p.high_water_low_water : [];
  return {
    id: feature.id,
    label: p.gauge_label || feature.id,
    area: p.area || "",
    region: p.region || "",
    state: p.state || "",
    hasCurve: curve.length > 0,
    hasMeasurement: curve.some(point => point.measurement !== undefined),
    hasTidalPrediction: curve.some(point => point.tidal_prediction !== undefined) || events.some(e => e.tidal_prediction_value !== undefined),
    hasCurveForecast: curve.some(point => point.automated_curve_forecast !== undefined),
    hasHighLowWater: events.length > 0,
    hasEventForecast: events.some(e => e.forecast_value !== undefined || e.mos_forecast_r0_value !== undefined)
  };
}

function normalizeFeature(feature, origin) {
  const p = feature.properties || {};
  const curve = Array.isArray(p.curve) ? p.curve : [];
  const eventsRaw = Array.isArray(p.high_water_low_water) ? p.high_water_low_water : [];

  const prediction = [];
  const measurement = [];
  const forecast = [];

  for (const point of curve) {
    const x = toMs(point.timestamp);
    if (!x) continue;
    const pred = cmToM(point.tidal_prediction);
    const meas = cmToM(point.measurement);
    const fc = cmToM(point.automated_curve_forecast ?? point.forecast);
    if (pred !== null) prediction.push({ x, y: pred });
    if (meas !== null) measurement.push({ x, y: meas });
    if (fc !== null) forecast.push({ x, y: fc });
  }

  const events = eventsRaw.map(e => {
    const x = toMs(e.event_timestamp);
    const tidal = cmToM(e.tidal_prediction_value);
    const forecastValue = cmToM(e.forecast_value ?? e.mos_forecast_r0_value);
    return {
      x,
      time: x ? new Date(x).toISOString() : null,
      event: e.event,
      label: e.event === "HW" ? "HW" : e.event === "NW" ? "NW" : e.event,
      tidalHeight: tidal,
      forecastHeight: forecastValue,
      height: forecastValue !== null ? forecastValue : tidal,
      deviation: e.forecast_deviation || e.mos_forecast_r0_deviation || "",
      uncertainty: cmToM(e.forecast_uncertainty)
    };
  }).filter(e => e.x && e.height !== null);

  const syntheticPrediction = curve.length === 0
    ? interpolateExtrema(eventsRaw.map(e => ({ x: toMs(e.event_timestamp), y: cmToM(e.tidal_prediction_value) })), 10)
    : [];
  const syntheticForecast = curve.length === 0
    ? interpolateExtrema(eventsRaw.map(e => ({ x: toMs(e.event_timestamp), y: cmToM(e.forecast_value ?? e.mos_forecast_r0_value) })), 10)
    : [];

  const eventSeriesDefs = [
    {
      key: "officialPeaks",
      name: "geprüfte, offizielle Scheitelwertvorhersage",
      color: "#204e74",
      valueField: "forecast_value",
      deviationField: "forecast_deviation",
      timestampField: "forecast_event_forecast_timestamp"
    },
    { key: "mosR0", name: "MOS R0 Scheitelwertvorhersage", color: "#7c3aed", valueField: "mos_forecast_r0_value", deviationField: "mos_forecast_r0_deviation", timestampField: "mos_forecast_event_forecast_timestamp" },
    { key: "mosR1", name: "MOS R1 Scheitelwertvorhersage", color: "#9333ea", valueField: "mos_forecast_r1_value", deviationField: "mos_forecast_r1_deviation", timestampField: "mos_forecast_event_forecast_timestamp" },
    { key: "mosR2", name: "MOS R2 Scheitelwertvorhersage", color: "#a855f7", valueField: "mos_forecast_r2_value", deviationField: "mos_forecast_r2_deviation", timestampField: "mos_forecast_event_forecast_timestamp" },
    { key: "mosR3", name: "MOS R3 Scheitelwertvorhersage", color: "#c084fc", valueField: "mos_forecast_r3_value", deviationField: "mos_forecast_r3_deviation", timestampField: "mos_forecast_event_forecast_timestamp" },
    { key: "mosR4", name: "MOS R4 Scheitelwertvorhersage", color: "#d946ef", valueField: "mos_forecast_r4_value", deviationField: "mos_forecast_r4_deviation", timestampField: "mos_forecast_event_forecast_timestamp" },
    { key: "mosR5", name: "MOS R5 Scheitelwertvorhersage", color: "#ec4899", valueField: "mos_forecast_r5_value", deviationField: "mos_forecast_r5_deviation", timestampField: "mos_forecast_event_forecast_timestamp" }
  ];

  const eventSeries = eventSeriesDefs.map(def => ({
    key: def.key,
    name: def.name,
    color: def.color,
    points: eventsRaw.map(e => eventSeriesPoint(e, def.key, def.name, def.color, def.valueField, def.deviationField, def.timestampField)).filter(Boolean)
  })).filter(s => s.points.length > 0);

  const allPoints = prediction.concat(measurement, forecast, syntheticPrediction, syntheticForecast, events.map(e => ({ x: e.x, y: e.height })), eventSeries.flatMap(s => s.points.map(p => ({ x: p.x, y: p.height }))));
  const dataUntil = latestTimestamp(allPoints);
  const dataFrom = earliestTimestamp(allPoints);

  const capabilities = {
    hasCurve: curve.length > 0,
    hasMeasurement: measurement.length > 0,
    hasTidalPrediction: prediction.length > 0 || events.some(e => e.tidalHeight !== null),
    hasCurveForecast: forecast.length > 0,
    hasHighLowWater: events.length > 0,
    hasEventForecast: events.some(e => e.forecastHeight !== null)
  };

  return {
    schemaVersion: 2,
    origin,
    station: {
      id: feature.id,
      name: p.gauge_label || feature.id,
      area: p.area || "",
      region: p.region || "",
      state: p.state || "",
      latitude: Number(p.latitude ?? feature.geometry?.coordinates?.[1]),
      longitude: Number(p.longitude ?? feature.geometry?.coordinates?.[0]),
      bshUrl: p.bsh_url_waterlevel || "",
      measurementUrl: p.measurement_url || ""
    },
    referenceLevels: {
      base: "pnp",
      gaugezeroRelativeToNhn: cmToM(p.gaugezero_relative_to_nhn),
      chartdatumRelativeToGaugezero: cmToM(p.chartdatum_relative_to_gaugezero),
      meanHighWater: cmToM(p.mean_high_water),
      meanLowWater: cmToM(p.mean_low_water),
      labels: {
        pnp: "Pegelnullpunkt (PNP)",
        skn: "Seekartennull (SKN)",
        nhn: "Normalhöhennull (NHN)"
      }
    },
    source: {
      name: "BSH WaterLevelForecast API",
      license: p.licence || "CC BY 4.0",
      fetchedAt: new Date().toISOString(),
      forecastTimestamp: toIso(p.forecast_timestamp),
      curveForecastTimestamp: toIso(p.automated_curveforecast_timestamp),
      dataFrom: dataFrom ? new Date(dataFrom).toISOString() : null,
      dataUntil: dataUntil ? new Date(dataUntil).toISOString() : null
    },
    capabilities,
    status: {
      text: [
        capabilities.hasCurveForecast ? "Kurven-Forecast vorhanden" : "Kein Kurven-Forecast",
        capabilities.hasEventForecast ? "HW/NW-Forecast vorhanden" : "Kein HW/NW-Forecast",
        capabilities.hasMeasurement ? "Messwerte vorhanden" : "Keine Messwerte",
        capabilities.hasTidalPrediction ? "Tidenvorhersage vorhanden" : "Keine Tidenvorhersage",
        syntheticForecast.length || syntheticPrediction.length ? "Kurve aus HW/NW interpoliert" : ""
      ].filter(Boolean).join(" · ")
    },
    chart: {
      series: [
        { key: "measurement", name: "Messwert", color: "#1f77b4", points: measurement },
        { key: "prediction", name: "Astronomische Tide", color: "#64748b", points: prediction },
        { key: "forecast", name: "BSH Forecast", color: "#f97316", points: forecast },
        { key: "syntheticPrediction", name: "Astronomische Tide interpoliert", color: "#64748b", points: syntheticPrediction, synthetic: true },
        { key: "syntheticForecast", name: "Forecast interpoliert aus HW/NW", color: "#f97316", points: syntheticForecast, synthetic: true }
      ].filter(s => s.points.length > 0),
      events,
      eventSeries
    },
    rawFeature: feature
  };
}

function uiPayload(extra = {}) {
  return {
    payload: {
      type: "state",
      stations: state.stations,
      activeStationId: state.activeStationId,
      selectedStations: state.selectedStations,
      offlineIndex: Object.values(state.offlineIndex || {}).sort((a, b) => (a.label || "").localeCompare(b.label || "")),
      seaWeatherIndex: Object.values(state.seaWeatherIndex || {}).sort((a, b) => String(b.savedAt || "").localeCompare(String(a.savedAt || ""))),
      navtexIndex: Object.values(state.navtexIndex || {}).sort((a, b) => String(b.savedAt || b.fetchedAt || "").localeCompare(String(a.savedAt || a.fetchedAt || ""))),
      activeData: state.activeStationId ? state.loaded[state.activeStationId] : null,
      mode: state.mode,
      status: state.status,
      appVersion: APP_VERSION,
      cacheDir: CACHE_DIR,
      seaWeatherCacheDir: SEAWEATHER_CACHE_DIR,
      pegelOnlineCacheDir: PEGELONLINE_CACHE_DIR,
      navtexCacheDir: NAVTEX_CACHE_DIR,
      copernicusConfigured: !!(flow.get("copernicusUsername") && flow.get("copernicusPassword")),
      copernicusUsername: flow.get("copernicusUsername") || "",
      copernicusStatus: flow.get("copernicusStatus") || "Bereit",
      copernicusLastTestAt: flow.get("copernicusLastTestAt") || "",
      copernicusExePath: flow.get("copernicusExePath") || "%USERPROFILE%\\Downloads\\copernicusmarine.exe",
      copernicusDataDir: flow.get("copernicusDataDir") || "C:\\signalk\\signalkhome\\.signalk\\copernicus-cache",
      copernicusWgrib2Path: flow.get("copernicusWgrib2Path") || "",
    copernicusWgrib2Args: flow.get("copernicusWgrib2Args") || "{input} -grib {output}",
      copernicusLastOutput: flow.get("copernicusLastOutput") || "",
      ...extra
    }
  };
}

function requestStation(id) {
  return {
    _bshAction: "station-response",
    _stationId: id,
    method: "GET",
    url: BASE_URL + "/" + encodeURIComponent(id) + "?f=json"
  };
}

const incoming = msg.payload || {};
const action = incoming.action || msg._bshAction || "unknown";

if (action === "get-state") {
  return [
    null,
    uiPayload(),
    null,
    [
      { _bshAction: "read-index", filename: joinPath(CACHE_DIR, "index.json") },
      { _bshAction: "read-seaweather-index", filename: joinPath(SEAWEATHER_CACHE_DIR, "seaweather-index.json") },
      { _bshAction: "read-navtex-index", filename: joinPath(NAVTEX_CACHE_DIR, "navtex-index.json") }
    ],
    null
  ];
}

if (action === "init" || action === "refresh-stations") {
  state.status = "Lade BSH-Stationsliste ...";
  saveState();
  return [
    [{ _bshAction: "stations-response", method: "GET", url: BASE_URL + "?f=json" }],
    uiPayload(),
    null,
    [
      { _bshAction: "read-index", filename: joinPath(CACHE_DIR, "index.json") },
      { _bshAction: "read-seaweather-index", filename: joinPath(SEAWEATHER_CACHE_DIR, "seaweather-index.json") },
      { _bshAction: "read-navtex-index", filename: joinPath(NAVTEX_CACHE_DIR, "navtex-index.json") }
    ]
  ];
}

if (action === "stations-response") {
  const features = Array.isArray(msg.payload?.features) ? msg.payload.features : [];
  state.stations = features.map(summarizeFeature).sort((a, b) => a.label.localeCompare(b.label));
  state.status = state.stations.length + " BSH-Stationen geladen";
  saveState();
  return [null, uiPayload(), null, null];
}

if (action === "read-index") {
  try {
    const parsed = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
    state.offlineIndex = parsed && parsed.stations ? parsed.stations : {};
    state.status = "Offline-Index geladen: " + Object.keys(state.offlineIndex).length + " Stationen";
  } catch (e) {
    state.offlineIndex = {};
    state.status = "Noch kein Offline-Index vorhanden";
  }
  saveState();
  return [null, uiPayload(), null, null];
}

if (action === "read-seaweather-index") {
  try {
    const parsed = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
    state.seaWeatherIndex = parsed && parsed.maps ? parsed.maps : {};
    state.status = "Seewetter-Offlinekarten geladen: " + Object.keys(state.seaWeatherIndex).length;
  } catch (e) {
    state.seaWeatherIndex = {};
    state.status = "Noch kein Seewetter-Offlineindex vorhanden";
  }
  saveState();
  return [null, uiPayload(), null, null, null];
}

if (action === "read-navtex-index") {
  try {
    const parsed = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
    state.navtexIndex = parsed && parsed.files ? parsed.files : {};
    state.status = "NAVTEX-Offlinedateien geladen: " + Object.keys(state.navtexIndex).length;
  } catch (e) {
    state.navtexIndex = {};
    state.status = "Noch kein NAVTEX-Offlineindex vorhanden";
  }
  saveState();
  return [null, uiPayload(), null, null, null, null];
}

if (action === "station-selected") {
  const id = incoming.stationId;
  if (!id) return [null, uiPayload({ error: "Keine Station ausgewählt" }), null, null];
  state.mode = "online";
  state.activeStationId = id;
  state.status = "Lade " + id + " ...";
  saveState();
  return [[requestStation(id)], uiPayload(), null, null];
}

if (action === "station-response") {
  const feature = msg.payload;
  if (!feature || feature.type !== "Feature") {
    state.status = "Fehler: Station " + msg._stationId + " konnte nicht geladen werden";
    saveState();
    return [null, uiPayload({ error: state.status }), null, null];
  }
  const normalized = normalizeFeature(feature, "online");
  state.loaded[normalized.station.id] = normalized;
  state.activeStationId = normalized.station.id;
  state.status = normalized.station.name + " geladen";
  saveState();
  return [null, uiPayload(), null, null];
}

if (action === "add-selected") {
  const id = state.activeStationId;
  if (id && !state.selectedStations.includes(id)) state.selectedStations.push(id);
  state.status = id ? ((state.loaded[id]?.station?.name || id) + " zur Speicherliste hinzugefügt") : "Keine aktive Station";
  saveState();
  return [null, uiPayload(), null, null];
}

if (action === "remove-selected") {
  const id = incoming.stationId;
  state.selectedStations = state.selectedStations.filter(x => x !== id);
  state.status = id + " aus Speicherliste entfernt";
  saveState();
  return [null, uiPayload(), null, null];
}

if (action === "save-selected") {
  const fileMessages = [];
  const missing = [];
  const index = { ...(state.offlineIndex || {}) };
  for (const id of state.selectedStations) {
    const data = state.loaded[id];
    if (!data) {
      missing.push(id);
      continue;
    }
    const safe = safeId(id);
    const filename = joinPath(CACHE_DIR, "bsh-tides-" + safe + "-latest.json");
    const savedAt = new Date().toISOString();
    const saveData = { ...data, origin: "offline-cache", savedAt, filename };
    index[id] = {
      id,
      label: data.station.name,
      area: data.station.area,
      region: data.station.region,
      savedAt,
      dataUntil: data.source.dataUntil,
      hasCurveForecast: data.capabilities.hasCurveForecast,
      hasEventForecast: data.capabilities.hasEventForecast,
      hasMeasurement: data.capabilities.hasMeasurement,
      filename
    };
    fileMessages.push({
      _bshAction: "file-written",
      _bshFileType: "station",
      _stationId: id,
      filename,
      payload: JSON.stringify(saveData, null, 2)
    });
  }
  state.offlineIndex = index;
  fileMessages.push({
    _bshAction: "file-written",
    _bshFileType: "index",
    filename: joinPath(CACHE_DIR, "index.json"),
    payload: JSON.stringify({ updatedAt: new Date().toISOString(), stations: index }, null, 2)
  });
  state.status = "Speichere " + (fileMessages.length - 1) + " Station(en)" + (missing.length ? " · nicht geladen: " + missing.join(", ") : "");
  saveState();
  return [null, uiPayload(), fileMessages, null];
}

