  let folderDeleted = false;
  if (folder && isPathInside(entry.cacheDir || flow.get("seaWeatherCacheDir") || SEAWEATHER_CACHE_DIR, folder)) {
    try {
      if (typeof fs !== "undefined" && fs.rmSync) {
        fs.rmSync(folder, { recursive: true, force: true });
        folderDeleted = true;
      }
    } catch (e) {
      state.status = "Ordner konnte nicht direkt gelöscht werden, lösche Dateien: " + e.message;
