function psQuote(value) {
  return "'" + String(value || "").replace(/'/g, "''") + "'";
}

function copernicusRegionBox(region) {
  const regions = {
    german_bight: { label: "Deutsche Bucht", minLon: 5.5, maxLon: 10.5, minLat: 53.0, maxLat: 56.5 },
    north_sea: { label: "Nordsee", minLon: -1.0, maxLon: 10.5, minLat: 51.0, maxLat: 59.0 },
    netherlands: { label: "Niederlande", minLon: 3.0, maxLon: 7.5, minLat: 51.0, maxLat: 54.5 }
  };
  return regions[region] || regions.german_bight;
}

function psArg(value) {
  return '"' + String(value || "").replace(/"/g, '\\"') + '"';
}

function copernicusExecMessage(actionName, script) {
  return {
    _bshAction: "copernicus-exec-response",
    _copernicusExecAction: actionName,
    payload: "-NoProfile -ExecutionPolicy Bypass -Command " + psArg(script)
  };
}

