if (action === "copernicus-convert-latest-grib2") {
  const wgrib2Path = flow.get("copernicusWgrib2Path") || "";
  const dataDir = flow.get("copernicusDataDir") || "C:\\signalk\\signalkhome\\.signalk\\copernicus-cache";
  const wgrib2Args = flow.get("copernicusWgrib2Args") || "{input} -grib {output}";
  if (!wgrib2Path) {
    flow.set("copernicusStatus", "wgrib2-Pfad fehlt");
    state.status = "Copernicus: wgrib2-Pfad fehlt";
    saveState();
    return [null, uiPayload(), null, null, null, null, null];
  }
  flow.set("copernicusStatus", "GRIB2-Konvertierung läuft ...");
  flow.set("copernicusLastOutput", "");
  state.status = "Copernicus: GRIB2-Konvertierung läuft";
  saveState();
  const script = [
    "$w=[Environment]::ExpandEnvironmentVariables(" + psQuote(wgrib2Path) + ")",
    "$dir=[Environment]::ExpandEnvironmentVariables(" + psQuote(dataDir) + ")",
    "if (!(Test-Path -LiteralPath $w)) { throw 'wgrib2.exe nicht gefunden: ' + $w }",
    "if (!(Test-Path -LiteralPath $dir)) { throw 'Datenordner nicht gefunden: ' + $dir }",
    "$nc=Get-ChildItem -LiteralPath $dir -Filter *.nc -File | Sort-Object LastWriteTime -Descending | Select-Object -First 1",
    "if (!$nc) { throw 'Keine .nc-Datei im Datenordner gefunden: ' + $dir }",
    "$out=[IO.Path]::ChangeExtension($nc.FullName, '.grb2')",
    "$argTemplate=" + psQuote(wgrib2Args),
    "$argLine=$argTemplate.Replace('{input}', $nc.FullName).Replace('{output}', $out)",
    "if (Test-Path -LiteralPath $out) { Remove-Item -LiteralPath $out -Force }",
    "$cmd='& ' + ('\"' + $w + '\"') + ' ' + $argLine",
    "Write-Output ('wgrib2 command: ' + $cmd)",
    "Invoke-Expression $cmd",
    "$written=Get-Item -LiteralPath $out -ErrorAction SilentlyContinue",
    "if (!$written -or $written.Length -le 0) { if ($written) { Remove-Item -LiteralPath $out -Force }; throw 'GRIB2-Konvertierung hat keine Daten geschrieben. Die Datei waere 0 KB. Bitte wgrib2-Konvertierungsparameter pruefen. NetCDF-Eingabe: ' + $nc.FullName }",
    "Write-Output ('GRIB2: ' + $out + ' (' + [Math]::Round($written.Length / 1KB, 1) + ' KB)')"
  ].join("; ");
  return [null, uiPayload(), null, null, null, null, [copernicusExecMessage("wgrib2-convert", script)]];
}

if (action === "copernicus-mini-download") {
  const username = flow.get("copernicusUsername") || "";
  const password = flow.get("copernicusPassword") || "";
