    saveState();
    return [null, uiPayload(), null, null, null, null, null];
  }
  const exePath = flow.get("copernicusExePath") || "%USERPROFILE%\\Downloads\\copernicusmarine.exe";
  const dataDir = flow.get("copernicusDataDir") || "C:\\signalk\\signalkhome\\.signalk\\copernicus-cache";
  const region = copernicusRegionBox(String(incoming.region || "german_bight"));
  const start = new Date();
  start.setUTCMinutes(0, 0, 0);
  const end = new Date(start.getTime() + 3 * 60 * 60 * 1000);
  function isoHour(d) { return d.toISOString().replace(/\.\d{3}Z$/, ""); }
  const stamp = start.toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "_");
  const outName = "copernicus_" + String(incoming.region || "german_bight") + "_" + stamp + ".nc";
  flow.set("copernicusStatus", "Mini-Testdownload läuft: " + region.label);
  flow.set("copernicusLastOutput", "");
  state.status = "Copernicus: Mini-Testdownload läuft";
  saveState();
  const script = [
    "$exe=[Environment]::ExpandEnvironmentVariables(" + psQuote(exePath) + ")",
    "$out=[Environment]::ExpandEnvironmentVariables(" + psQuote(dataDir) + ")",
    "New-Item -ItemType Directory -Force -Path $out | Out-Null",
    "$env:COPERNICUSMARINE_SERVICE_USERNAME=" + psQuote(username),
    "$env:COPERNICUSMARINE_SERVICE_PASSWORD=" + psQuote(password),
    "if (!(Test-Path -LiteralPath $exe)) { throw 'copernicusmarine.exe nicht gefunden: ' + $exe }",
    "& $exe subset --dataset-id cmems_mod_nws_phy-cur_anfc_1.5km-2D_PT1H-i --variable uo --variable vo --minimum-longitude " + region.minLon + " --maximum-longitude " + region.maxLon + " --minimum-latitude " + region.minLat + " --maximum-latitude " + region.maxLat + " --start-datetime " + isoHour(start) + " --end-datetime " + isoHour(end) + " --output-directory $out --output-filename " + outName
  ].join("; ");
  return [null, uiPayload(), null, null, null, null, [copernicusExecMessage("mini-download", script)]];
}

if (action === "copernicus-exec-response") {
  const execAction = msg._copernicusExecAction || "exec";
  const labels = { "mini-download": "Mini-Testdownload", "toolbox-test": "Toolbox-Test", "wgrib2-test": "wgrib2-Test", "wgrib2-convert": "GRIB2-Konvertierung" };
  const label = labels[execAction] || "Tool-Ausführung";
  const stamp = new Date().toISOString();
  const payloadIsObject = msg.payload && typeof msg.payload === "object";
  const rc = payloadIsObject && msg.payload.code !== undefined
    ? msg.payload.code
    : msg.rc && typeof msg.rc === "object"
      ? msg.rc.code
      : msg.rc;
  const ok = rc === undefined || rc === 0 || rc === "0";
  let output = "";
  if (payloadIsObject) {
    output = flow.get("copernicusLastOutput") || JSON.stringify(msg.payload, null, 2);
  } else {
    output = String(msg.payload || "").trim();
    if (output) {
      const previous = flow.get("copernicusLastOutput") || "";
      output = previous && previous !== output ? previous + "\n" + output : output;
    } else {
      output = flow.get("copernicusLastOutput") || "";
    }
  }
  flow.set("copernicusLastTestAt", stamp);
  flow.set("copernicusLastOutput", output || (ok ? label + " beendet." : label + " ohne Ausgabe."));
  flow.set("copernicusStatus", ok ? (label + " erfolgreich") : (label + " Fehler" + (rc !== undefined ? " rc=" + rc : "")));
  state.status = "Copernicus: " + flow.get("copernicusStatus");
  saveState();
  return [null, uiPayload(), null, null, null, null, null];
}


